O=Path(__file__).resolve().parent
W=O.parents[1]
R=W/'research/remediation_round3'
def load(p): return json.loads(p.read_text(encoding='utf-8'))
def save(n,d): (O/n).write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8')
def md(n,t): (O/n).write_text(t,encoding='utf-8')
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
original_manifest=load(O/'initial_manifest.json')
current_manifest=load(R/'final_manifest.json')
if current_manifest['snapshot_sha256']!=original_manifest['executor_snapshot_id'] or any(sha(W/x['path'])!=x['sha256'] for x in current_manifest['files']):
    raise RuntimeError('Original audit snapshot changed; preserve this conclusion and create a separate revision instead of rerunning this writer.')
S=load(R/'sources.json')
rules={p.stem:yaml.safe_load(p.read_text(encoding='utf-8')) for p in (R/'rules').glob('*.yaml')}
